-- 090 AI development assistant durable contracts; forward-only and idempotent.
SET @schema_name=DATABASE();

SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_conversation'),'CREATE TABLE `fun_ai_conversation` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`admin_id` bigint unsigned NOT NULL,`uuid` char(36) NOT NULL,`title` varchar(255) NOT NULL DEFAULT \'\',`status` enum(\'draft\',\'planning\',\'awaiting_approval\',\'running\',\'reviewing\',\'applying\',\'completed\',\'paused\',\'cancelled\',\'failed\',\'conflict\',\'recovery_required\') NOT NULL DEFAULT \'draft\',`approval_mode` enum(\'request_approval\',\'agent_approval\',\'full_access\') NOT NULL DEFAULT \'request_approval\',`provider` varchar(64) NOT NULL DEFAULT \'\',`model` varchar(128) NOT NULL DEFAULT \'\',`context` json DEFAULT NULL,`created_at` datetime NULL,`updated_at` datetime NULL,`deleted_at` datetime NULL,PRIMARY KEY (`id`),UNIQUE KEY `uk_ai_conversation_uuid` (`uuid`),KEY `idx_ai_conversation_admin_status` (`admin_id`,`status`),KEY `idx_ai_conversation_deleted` (`deleted_at`),CONSTRAINT `fk_ai_conversation_admin` FOREIGN KEY (`admin_id`) REFERENCES `fun_admin` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT=\'AI conversation\'','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_message'),'CREATE TABLE `fun_ai_message` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`conversation_id` bigint unsigned NOT NULL,`parent_id` bigint unsigned NULL,`sequence` int unsigned NOT NULL,`role` enum(\'system\',\'user\',\'assistant\',\'tool\') NOT NULL,`content` json NOT NULL,`metadata` json DEFAULT NULL,`usage` json DEFAULT NULL,`created_at` datetime NULL,`updated_at` datetime NULL,`deleted_at` datetime NULL,PRIMARY KEY (`id`),UNIQUE KEY `uk_ai_message_sequence` (`conversation_id`,`sequence`),KEY `idx_ai_message_conversation_sequence` (`conversation_id`,`sequence`),KEY `idx_ai_message_parent` (`parent_id`),KEY `idx_ai_message_deleted` (`deleted_at`),CONSTRAINT `fk_ai_message_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `fun_ai_conversation` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `fk_ai_message_parent` FOREIGN KEY (`parent_id`) REFERENCES `fun_ai_message` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT=\'AI message\'','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_task'),'CREATE TABLE `fun_ai_task` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`conversation_id` bigint unsigned NOT NULL,`message_id` bigint unsigned NULL,`parent_id` bigint unsigned NULL,`change_set_id` bigint unsigned NULL,`idempotency_key` varchar(128) NOT NULL,`operation_token` char(64) NOT NULL,`type` enum(\'chat\',\'crud\',\'code_change\',\'fix\',\'test\',\'migration\') NOT NULL,`stage` varchar(64) NOT NULL DEFAULT \'\',`status` enum(\'pending\',\'running\',\'succeeded\',\'failed\',\'cancelled\',\'paused\',\'recovery_required\') NOT NULL DEFAULT \'pending\',`approval_mode` enum(\'request_approval\',\'agent_approval\',\'full_access\') NOT NULL,`provider` varchar(64) NOT NULL DEFAULT \'\',`model` varchar(128) NOT NULL DEFAULT \'\',`container_task_id` varchar(128) NULL,`max_rounds` int unsigned NOT NULL DEFAULT 0,`timeout_seconds` int unsigned NOT NULL DEFAULT 0,`max_cost` decimal(12,4) NOT NULL DEFAULT 0.0000,`input_token_budget` bigint unsigned NOT NULL DEFAULT 0,`output_token_budget` bigint unsigned NOT NULL DEFAULT 0,`total_token_budget` bigint unsigned NOT NULL DEFAULT 0,`usage` json DEFAULT NULL,`input` json DEFAULT NULL,`output` json DEFAULT NULL,`error` json DEFAULT NULL,`result_summary` text NULL,`test_result` json DEFAULT NULL,`recovery_status` enum(\'none\',\'recovery_required\',\'recovering\',\'recovered\',\'failed\') NOT NULL DEFAULT \'none\',`started_at` datetime NULL,`completed_at` datetime NULL,`created_at` datetime NULL,`updated_at` datetime NULL,`deleted_at` datetime NULL,PRIMARY KEY (`id`),UNIQUE KEY `uk_ai_task_idempotency` (`conversation_id`,`idempotency_key`),UNIQUE KEY `uk_ai_task_operation_token` (`operation_token`),KEY `idx_ai_task_conversation_status` (`conversation_id`,`status`),KEY `idx_ai_task_message` (`message_id`),KEY `idx_ai_task_parent` (`parent_id`),KEY `idx_ai_task_change_set` (`change_set_id`),KEY `idx_ai_task_container` (`container_task_id`),KEY `idx_ai_task_deleted` (`deleted_at`),CONSTRAINT `fk_ai_task_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `fun_ai_conversation` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `fk_ai_task_message` FOREIGN KEY (`message_id`) REFERENCES `fun_ai_message` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT `fk_ai_task_parent` FOREIGN KEY (`parent_id`) REFERENCES `fun_ai_task` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT=\'AI task\'','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_tool_call'),'CREATE TABLE `fun_ai_tool_call` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`conversation_id` bigint unsigned NOT NULL,`task_id` bigint unsigned NOT NULL,`message_id` bigint unsigned NULL,`approval_id` bigint unsigned NULL,`idempotency_key` varchar(128) NOT NULL,`tool_name` varchar(128) NOT NULL,`operation` varchar(64) NOT NULL,`risk_level` enum(\'low\',\'medium\',\'high\',\'critical\') NOT NULL DEFAULT \'low\',`status` enum(\'pending\',\'awaiting_approval\',\'running\',\'succeeded\',\'failed\',\'denied\') NOT NULL DEFAULT \'pending\',`redacted_arguments` json NOT NULL,`approval_decision` enum(\'not_required\',\'pending\',\'approved\',\'denied\',\'expired\',\'cancelled\') NOT NULL DEFAULT \'not_required\',`result` json DEFAULT NULL,`error` json DEFAULT NULL,`exit_code` int NULL,`stdout_summary` text NULL,`stdout_hash` char(64) NULL,`stdout_path` varchar(1024) NULL,`stderr_summary` text NULL,`stderr_hash` char(64) NULL,`stderr_path` varchar(1024) NULL,`duration_ms` bigint unsigned NULL,`side_effects` json DEFAULT NULL,`started_at` datetime NULL,`completed_at` datetime NULL,`created_at` datetime NULL,`updated_at` datetime NULL,PRIMARY KEY (`id`),UNIQUE KEY `uk_ai_tool_call_idempotency` (`conversation_id`,`idempotency_key`),KEY `idx_ai_tool_call_task_status` (`task_id`,`status`),KEY `idx_ai_tool_call_conversation` (`conversation_id`,`created_at`),KEY `idx_ai_tool_call_message` (`message_id`),KEY `idx_ai_tool_call_approval` (`approval_id`),CONSTRAINT `fk_ai_tool_call_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `fun_ai_conversation` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `fk_ai_tool_call_task` FOREIGN KEY (`task_id`) REFERENCES `fun_ai_task` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `fk_ai_tool_call_message` FOREIGN KEY (`message_id`) REFERENCES `fun_ai_message` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT=\'Immutable AI tool call security record\'','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_approval'),'CREATE TABLE `fun_ai_approval` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`conversation_id` bigint unsigned NOT NULL,`task_id` bigint unsigned NOT NULL,`tool_call_id` bigint unsigned NOT NULL,`requested_by` bigint unsigned NOT NULL,`decided_by` bigint unsigned NULL,`scope` enum(\'once\',\'session_operation\') NOT NULL DEFAULT \'once\',`risk_reason` text NOT NULL,`impact` json NOT NULL,`cas_version` bigint unsigned NOT NULL DEFAULT 0,`nonce` char(64) NOT NULL,`digest` char(64) NOT NULL,`operation` varchar(64) NOT NULL,`mode_snapshot` enum(\'request_approval\',\'agent_approval\',\'full_access\') NOT NULL,`status` enum(\'pending\',\'approved\',\'denied\',\'expired\',\'cancelled\') NOT NULL DEFAULT \'pending\',`request` json NOT NULL,`decision` json DEFAULT NULL,`expires_at` datetime NULL,`decided_at` datetime NULL,`created_at` datetime NULL,`updated_at` datetime NULL,`deleted_at` datetime NULL,PRIMARY KEY (`id`),UNIQUE KEY `uk_ai_approval_nonce` (`nonce`),UNIQUE KEY `uk_ai_approval_digest` (`conversation_id`,`digest`),KEY `idx_ai_approval_conversation_status` (`conversation_id`,`status`),KEY `idx_ai_approval_task` (`task_id`),KEY `idx_ai_approval_tool_call` (`tool_call_id`),KEY `idx_ai_approval_requested_by` (`requested_by`),KEY `idx_ai_approval_decided_by` (`decided_by`),KEY `idx_ai_approval_deleted` (`deleted_at`),CONSTRAINT `fk_ai_approval_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `fun_ai_conversation` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `fk_ai_approval_task` FOREIGN KEY (`task_id`) REFERENCES `fun_ai_task` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `fk_ai_approval_tool_call` FOREIGN KEY (`tool_call_id`) REFERENCES `fun_ai_tool_call` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `fk_ai_approval_requested_by` FOREIGN KEY (`requested_by`) REFERENCES `fun_admin` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `fk_ai_approval_decided_by` FOREIGN KEY (`decided_by`) REFERENCES `fun_admin` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT=\'AI approval\'','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_change_set'),'CREATE TABLE `fun_ai_change_set` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`conversation_id` bigint unsigned NOT NULL,`task_id` bigint unsigned NOT NULL,`approval_id` bigint unsigned NULL,`final_approval_id` bigint unsigned NULL,`created_by` bigint unsigned NOT NULL,`applied_by` bigint unsigned NULL,`idempotency_key` varchar(128) NOT NULL,`digest` char(64) NOT NULL,`patch_path` varchar(1024) NOT NULL,`patch_sha256` char(64) NOT NULL,`base_file_hashes` json NOT NULL,`added_count` int unsigned NOT NULL DEFAULT 0,`modified_count` int unsigned NOT NULL DEFAULT 0,`deleted_count` int unsigned NOT NULL DEFAULT 0,`renamed_count` int unsigned NOT NULL DEFAULT 0,`test_status` enum(\'pending\',\'running\',\'passed\',\'failed\',\'skipped\') NOT NULL DEFAULT \'pending\',`test_result` json DEFAULT NULL,`security_status` enum(\'pending\',\'running\',\'passed\',\'failed\',\'skipped\') NOT NULL DEFAULT \'pending\',`security_result` json DEFAULT NULL,`transaction_id` varchar(128) NULL,`recovery_status` enum(\'none\',\'recovery_required\',\'recovering\',\'recovered\',\'failed\') NOT NULL DEFAULT \'none\',`status` enum(\'proposed\',\'approved\',\'applying\',\'applied\',\'rejected\',\'failed\',\'conflict\',\'recovery_required\') NOT NULL DEFAULT \'proposed\',`manifest` json NOT NULL,`summary` json DEFAULT NULL,`base_revision` varchar(128) NOT NULL DEFAULT \'\',`applied_revision` varchar(128) NOT NULL DEFAULT \'\',`applied_at` datetime NULL,`created_at` datetime NULL,`updated_at` datetime NULL,`deleted_at` datetime NULL,PRIMARY KEY (`id`),UNIQUE KEY `uk_ai_change_set_idempotency` (`conversation_id`,`idempotency_key`),UNIQUE KEY `uk_ai_change_set_digest` (`conversation_id`,`digest`),UNIQUE KEY `uk_ai_change_set_transaction` (`transaction_id`),KEY `idx_ai_change_set_conversation_status` (`conversation_id`,`status`),KEY `idx_ai_change_set_task` (`task_id`),KEY `idx_ai_change_set_approval` (`approval_id`),KEY `idx_ai_change_set_final_approval` (`final_approval_id`),KEY `idx_ai_change_set_created_by` (`created_by`),KEY `idx_ai_change_set_applied_by` (`applied_by`),KEY `idx_ai_change_set_deleted` (`deleted_at`),CONSTRAINT `fk_ai_change_set_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `fun_ai_conversation` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `fk_ai_change_set_task` FOREIGN KEY (`task_id`) REFERENCES `fun_ai_task` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `fk_ai_change_set_approval` FOREIGN KEY (`approval_id`) REFERENCES `fun_ai_approval` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `fk_ai_change_set_final_approval` FOREIGN KEY (`final_approval_id`) REFERENCES `fun_ai_approval` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `fk_ai_change_set_created_by` FOREIGN KEY (`created_by`) REFERENCES `fun_admin` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `fk_ai_change_set_applied_by` FOREIGN KEY (`applied_by`) REFERENCES `fun_admin` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT=\'AI change set\'','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_task' AND CONSTRAINT_NAME='fk_ai_task_change_set'),'ALTER TABLE `fun_ai_task` ADD CONSTRAINT `fk_ai_task_change_set` FOREIGN KEY (`change_set_id`) REFERENCES `fun_ai_change_set` (`id`) ON DELETE SET NULL ON UPDATE CASCADE','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_tool_call' AND CONSTRAINT_NAME='fk_ai_tool_call_approval'),'ALTER TABLE `fun_ai_tool_call` ADD CONSTRAINT `fk_ai_tool_call_approval` FOREIGN KEY (`approval_id`) REFERENCES `fun_ai_approval` (`id`) ON DELETE SET NULL ON UPDATE CASCADE','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
